  struct PStack {
    int width;
    int height;
    int depth;
    uint8_t *array;
  };

  struct PStack Python_Stack(const Stack *stack) {
    struct PStack out;
    out.width = stack->width;
    out.height = stack->height;
    out.depth = stack->depth;
    out.array = stack->array;

    return out;
  }

  void DeleteStackObject(ZStack *stack) {
    delete stack;
  }

